import test from 'node:test';import assert from 'node:assert/strict';import {PDFDocument,StandardFonts,degrees} from 'pdf-lib';import {routeInvoiceBundle,bundleOptions,routeInvoiceIds,routeInvoiceSelection} from '../src/warehouse_invoice_bundle.js';import fs from 'node:fs/promises';
const packet={route:{id:'R1',name:'Practice route',date:'2026-11-01',driver:'Practice Driver',vehicle:'Ford Transit'},checklist:[{name:'Fresh Dole bananas',qty:8,pack:'40 lb case',group:'Fresh fruit / produce'},{name:'Orange juice',qty:4,pack:'12 bottles per case',group:'Juices'},{name:'Acai sorbet',qty:20,pack:'3 gallon tub',group:'Other products'}],invoices:[{qboInvoiceId:'101',invoice:'A'},{qboInvoiceId:'102',invoice:'B'}]};
async function document(label,pages=1){const d=await PDFDocument.create(),font=await d.embedFont(StandardFonts.Helvetica);for(let i=0;i<pages;i++){const p=d.addPage([612,792]);p.drawText('Invoice '+label+' · page '+(i+1),{x:45,y:730,size:20,font});p.drawRectangle({x:35,y:35,width:542,height:722,borderWidth:1});}return d.save();}
test('two paired copies preserve entire multi-page invoices on Letter paper',async()=>{const docs={'101':await document('A',2),'102':await document('B')},calls=[];const bundle=await routeInvoiceBundle(packet,{},async i=>{calls.push(i.qboInvoiceId);return docs[i.qboInvoiceId];});assert.deepEqual(calls,['101','102']);assert.equal(bundle.pages,7);assert.equal(bundle.copies,2);const result=await PDFDocument.load(bundle.bytes);assert.ok(result.getPages().every(p=>p.getWidth()===612&&p.getHeight()===792));await fs.writeFile('../../outputs/route-invoice-bundle-practice.pdf',bundle.bytes);});
test('reverse order fetches last stop first and unavailable PDFs never return a partial bundle',async()=>{const calls=[];await routeInvoiceBundle(packet,{copies:1,order:'reverse'},async i=>{calls.push(i.qboInvoiceId);return document(i.invoice);});assert.deepEqual(calls,['102','101']);await assert.rejects(routeInvoiceBundle(packet,{},async i=>i.qboInvoiceId==='101'?document('A'):Buffer.from('invalid')),/invoice #B.*No partial bundle/);await assert.rejects(routeInvoiceBundle({...packet,invoices:[{invoice:'X'}]},{},()=>{}),/missing its QuickBooks link/);assert.throws(()=>bundleOptions({copies:0}),/1–3/);assert.throws(()=>bundleOptions({order:'arbitrary'}),/route order/);});
test('rotated originals remain inside Letter boundaries',async()=>{const d=await PDFDocument.create();for(const angle of [0,90,180,270])d.addPage([792,612]).setRotation(degrees(angle));const bundle=await routeInvoiceBundle({...packet,invoices:[packet.invoices[0]]},{copies:1},async()=>d.save());assert.equal(bundle.pages,5);});

test('selected routes make one PDF, each with its own summary and paired invoice copies',async()=>{const packets=[{...packet,invoices:[packet.invoices[0]]},{...packet,route:{...packet.route,id:'R2',name:'South practice'},invoices:[packet.invoices[1]]}],docs={'101':await document('A',2),'102':await document('B')};const batch=await routeInvoiceSelection(packets,{copies:2},async i=>docs[i.qboInvoiceId]);assert.equal(batch.pages,8);assert.deepEqual(batch.routes.map(r=>[r.startPage,r.pages]),[[1,5],[6,3]]);assert.deepEqual(routeInvoiceIds(JSON.stringify(['R1','R2','R1'])),['R1','R2']);assert.throws(()=>routeInvoiceIds('bad'),/Choose routes/);assert.throws(()=>routeInvoiceIds([]),/1 and 20/);await assert.rejects(routeInvoiceSelection(packets,{},async i=>i.qboInvoiceId==='102'?Buffer.from('invalid'):docs[i.qboInvoiceId]),/South practice.*No partial bundle/);});

test('loading checklist always stays one Letter page for long names and large product lists',async()=>{
 for(const count of [0,9,18,40,100]){
  const checklist=Array.from({length:count},(_,i)=>({name:'Item '+String(i+1).padStart(3,'0')+' - '+(i%2?'Fresh blueberries premium large case 12 x 12 ounces':'Cold pressed organic juice variety bottles 12 x 16 ounces'),qty:i+1,pack:'12 bottles per case',group:i%2?'Fresh fruit / produce':'Juices'}));
  const bundle=await routeInvoiceBundle({...packet,checklist,invoices:[packet.invoices[0]]},{copies:2},async()=>document('A',2));
  assert.equal(bundle.summaryPages,1,'checklist count '+count);assert.equal(bundle.pages,5);const pdf=await PDFDocument.load(bundle.bytes);assert.equal(pdf.getPage(0).getWidth(),612);assert.equal(pdf.getPage(0).getHeight(),792);
  if(count===18)await fs.writeFile('../../outputs/driver-checklist-single-page.pdf',bundle.bytes);
 }
});
